pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 blockNum, address sender) public {
        vm.assume(sender != address(0));
        vm.assume(blockNum > 0);
        vm.deal(sender, 10 ether);
        vm.roll(blockNum);
        vm.warp(block.timestamp + 1);
        vm.prank(sender);
        (bool ok,) = address(c).call{value: 10 ether}("");
        assertTrue(ok);
        if (blockNum % 15 == 0) {
            assertTrue(address(c).balance == 0);
        }
    }
}
